"""Paint Irises through the eai-standard Robot API. Resume-safe, no simulator reset."""
import os, sys, json, argparse, time
import numpy as np
from PIL import Image
from scipy.ndimage import gaussian_filter
sys.path.insert(0, '/opt/tools')
from rcb_client import Robot
ROOT='/app/output'
PLAN=ROOT+'/plan.json'; PROGRESS=ROOT+'/progress.json'
Q=np.array([0.,1.,0.,0.])
Z_UP=.046; Z_PAINT=.0148; Z_WELL=.023
X_FAR=.0135925; Y_LEFT=.1135925; SIZE=.227185

def rgb2lab(rgb):
    rgb=np.asarray(rgb,float)
    lin=np.where(rgb<=.04045,rgb/12.92,((rgb+.055)/1.055)**2.4)
    xyz=lin @ np.array([[.4124564,.3575761,.1804375],[.2126729,.7151522,.0721750],[.0193339,.1191920,.9503041]]).T
    xyz=xyz/np.array([.95047,1.,1.08883]); f=np.where(xyz>(6/29)**3,np.cbrt(xyz),xyz/(3*(6/29)**2)+4/29)
    return np.stack([116*f[...,1]-16,500*(f[...,0]-f[...,1]),200*(f[...,1]-f[...,2])],axis=-1)

def make_plan(r):
    spec=r.spec(); pal=np.array([w['rgb'] for w in spec['static']['wells']['wells']]); plab=rgb2lab(pal.reshape(1,16,3)).reshape(16,3)
    im=np.array(Image.open('/app/target.png').convert('RGB'))/255.
    lab=rgb2lab(im); ns=220; S=32; samplex=np.linspace(0,1023,ns).astype(int); pen=1000.
    strokes=[]
    for j in range(S):
        y0=j*1024//S; y1=(j+1)*1024//S
        A=lab[y0:y1].mean(0)[samplex]
        E=((A[:,None,:]-plab[None,:,:])**2).sum(2)
        D=np.empty_like(E); P=np.zeros_like(E,dtype=np.int16);D[0]=E[0]
        for k in range(1,ns):
            lo=np.argmin(D[k-1]); base=D[k-1,lo]+pen
            D[k]=E[k]+np.minimum(D[k-1],base)
            P[k]=np.where(D[k-1]<=base,np.arange(16),lo)
        q=np.empty(ns,dtype=np.int16);q[-1]=np.argmin(D[-1])
        for k in range(ns-2,-1,-1):q[k]=P[k+1,q[k+1]]
        cuts=np.r_[0,np.where(np.diff(q)!=0)[0]+1,ns]
        x=X_FAR-((j+.5)/S)*SIZE
        for a,b in zip(cuts[:-1],cuts[1:]):
            # Extend color regions slightly along the line to close paint gaps.
            u0=max(1.,a*1024/ns-5.);u1=min(1023.,b*1024/ns+5.)
            yl=Y_LEFT-u0/1024*SIZE; yr=Y_LEFT-u1/1024*SIZE
            strokes.append(dict(color=int(q[a]),row=j,p0=[x,yl],p1=[x,yr],u0=u0,u1=u1))
    # Ground and foliage first; flower blues and darkest accents last.
    order=[7,8,6,11,1,2,0,3,4,5,10,12,9,13,14,15]
    sorted_strokes=[]; last=np.array([0.,0.])
    for c in order:
        remaining=[s for s in strokes if s['color']==c]
        while remaining:
            best=None; metric=np.inf; rev=False
            for i,s in enumerate(remaining):
                p0=np.array(s['p0']);p1=np.array(s['p1'])
                a=np.linalg.norm(p0-last);b=np.linalg.norm(p1-last)
                if min(a,b)<metric: metric=min(a,b);best=i;rev=(b<a)
            s=remaining.pop(best)
            if rev:s['p0'],s['p1']=s['p1'],s['p0']
            sorted_strokes.append(s);last=np.array(s['p1'])
    with open(PLAN,'w') as f:json.dump(sorted_strokes,f)
    print('Generated',len(sorted_strokes),'strokes',flush=True)
    return sorted_strokes

def well(c):
    # Derived from the palette pixels in scene_cam + depth geometry.
    if c<6:col,row=0,c
    elif c<12:col,row=1,c-6
    else:col,row=2,c-12+1
    return np.array([-.1575+.0225*row,.1395+.0205*col,.023])

def path(cur,points):
    arr=[]; p=np.array(cur,float)
    for dest,spacing,hold in points:
        dest=np.array(dest,float);n=max(1,int(np.ceil(np.linalg.norm(dest-p)/spacing)))
        for v in np.linspace(p,dest,n+1)[1:]:arr.append(np.r_[v,Q])
        for _ in range(hold):arr.append(np.r_[dest,Q])
        p=dest
    return np.array(arr,dtype=float)

def save_progress(data):
    tmp=PROGRESS+'.tmp'
    with open(tmp,'w') as f:json.dump(data,f)
    os.replace(tmp,PROGRESS)

def action(r,progress,pts,note):
    cur=np.array(progress['tip'],float);A=path(cur,pts)
    if len(A)>200:raise RuntimeError(f'Action too long: {len(A)} {note}')
    before=r.status()['control_steps']; progress['pending']={'before':before,'rows':len(A),'note':note};save_progress(progress)
    try:
        res=r.submit('ee_pose',A,dt=.05,video='none',cameras=['scene_cam'],note=note)
    except Exception:
        r.wait_ready();now=r.status()['control_steps']
        if now==before:res=r.submit('ee_pose',A,dt=.05,video='none',cameras=['scene_cam'],note=note)
        elif now==before+len(A):
            progress['tip']=list(A[-1,:3]);progress['pending']=None;save_progress(progress)
            return
        else:raise RuntimeError(f'Uncertain action execution: {before} -> {now}, expected {len(A)}')
    if res.meta.get('stopped') or res.meta.get('done') or res.meta.get('executed_rows')!=len(A):
        raise RuntimeError(f'Action incomplete {note}: {res.meta}')
    fail=sum(x['ik_failures'] for x in res.meta['plan'])
    if fail: print('IK FAIL',note,fail,flush=True)
    progress['tip']=list(res.meta['proprio']['now'][7:10]);progress['pending']=None
    save_progress(progress)

def main():
    ap=argparse.ArgumentParser();ap.add_argument('--limit',type=int,default=0);args=ap.parse_args()
    r=Robot();st=r.status();print('start status',st,flush=True)
    strokes=json.load(open(PLAN)) if os.path.exists(PLAN) else make_plan(r)
    if os.path.exists(PROGRESS): progress=json.load(open(PROGRESS))
    else:
        obs=r.get_obs();progress={'next':0,'loaded':None,'tip':list(obs.meta['proprio']['now'][7:10]),'pending':None,'count':0};save_progress(progress)
    if progress.get('pending'):
        pd=progress['pending'];now=r.status()['control_steps']
        if now==pd['before']:progress['pending']=None;save_progress(progress)
        elif now==pd['before']+pd['rows']:
            raise RuntimeError('Completed pending action; inspect progress and resume manually to preserve stroke count')
        else:raise RuntimeError('Partial pending action; inspect status')
    limit=len(strokes) if args.limit<=0 else min(len(strokes),progress['next']+args.limit)
    for i in range(progress['next'],limit):
        s=strokes[i];c=s['color']
        if progress['loaded']!=c:
            wp=well(c); p=progress['tip'];
            pts=[([p[0],p[1],.065],.007,2),([wp[0],wp[1],.065],.008,3),(wp,.005,10),([wp[0],wp[1],.065],.005,3)]
            action(r,progress,pts,f'dip paint{c+1:02d}')
            progress['loaded']=c;save_progress(progress)
        p0=np.array([*s['p0'],Z_PAINT]);p1=np.array([*s['p1'],Z_PAINT]);
        up0=p0.copy();up0[2]=Z_UP;up1=p1.copy();up1[2]=Z_UP
        pts=[(up0,.008,3),(p0,.0045,4),(p1,.003,3),(up1,.0045,3)]
        action(r,progress,pts,f'stroke {i+1}/{len(strokes)} paint{c+1:02d} row{s["row"]}')
        progress['next']=i+1;progress['count']+=1;save_progress(progress)
        if (i+1)%10==0 or i+1==limit:
            print('PAINTED',i+1,'/',len(strokes),'step',r.status()['control_steps'],'time',round(r.get_obs(cameras=['scene_cam']).meta['time_left_s']),flush=True)
    print('DONE STAGE',progress['next'],r.status(),flush=True)
if __name__=='__main__':main()
